CREATE TABLE owner(subject TEXT PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE credentials(id TEXT PRIMARY KEY, ciphertext TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE web_sessions(token_hash TEXT PRIMARY KEY, subject TEXT NOT NULL, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE devices(id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT UNIQUE NOT NULL, revoked_at INTEGER);
CREATE TABLE pairing_requests(id TEXT PRIMARY KEY, code_hash TEXT UNIQUE NOT NULL, poll_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'pending', delivery_ciphertext TEXT, device_id TEXT REFERENCES devices(id), delivered_at INTEGER);
CREATE TABLE movies(id TEXT PRIMARY KEY, title TEXT NOT NULL, year INTEGER, description TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE source_files(id TEXT PRIMARY KEY, movie_id TEXT NOT NULL REFERENCES movies(id), generation TEXT NOT NULL, size_bytes TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', parent_id TEXT, mime_type TEXT, available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)), metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE editions(id TEXT PRIMARY KEY, movie_id TEXT NOT NULL REFERENCES movies(id), source_id TEXT REFERENCES source_files(id), label TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'source', generation TEXT NOT NULL);
CREATE TABLE tracks(id TEXT PRIMARY KEY, edition_id TEXT NOT NULL REFERENCES editions(id), kind TEXT NOT NULL, codec TEXT NOT NULL, language TEXT, metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE artwork(id TEXT PRIMARY KEY, movie_id TEXT NOT NULL REFERENCES movies(id), path TEXT NOT NULL, provider TEXT NOT NULL);
CREATE TABLE preferences(id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL);
CREATE TABLE watchlist(movie_id TEXT PRIMARY KEY REFERENCES movies(id), created_at INTEGER NOT NULL);
CREATE TABLE playback_sessions(id TEXT PRIMARY KEY, ticket_hash TEXT UNIQUE NOT NULL, movie_id TEXT NOT NULL REFERENCES movies(id), source_id TEXT NOT NULL REFERENCES source_files(id), generation TEXT NOT NULL, device_id TEXT REFERENCES devices(id), web_session_hash TEXT, epoch INTEGER NOT NULL UNIQUE, lease_until INTEGER NOT NULL, access_until INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE TABLE progress(movie_id TEXT PRIMARY KEY REFERENCES movies(id), session_id TEXT NOT NULL, epoch INTEGER NOT NULL, sequence INTEGER NOT NULL, position_ms REAL NOT NULL CHECK(position_ms>=0), ended INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL);
CREATE TABLE jobs(id TEXT PRIMARY KEY, unique_key TEXT UNIQUE NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', lease_until INTEGER, attempts INTEGER NOT NULL DEFAULT 0, error_code TEXT);
CREATE TABLE cache_blocks(key TEXT PRIMARY KEY, source_id TEXT NOT NULL, generation TEXT NOT NULL, block_index INTEGER NOT NULL, size_bytes INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'writing', last_used INTEGER NOT NULL);
CREATE TABLE sync_checkpoints(id TEXT PRIMARY KEY, token TEXT, state TEXT NOT NULL DEFAULT 'idle', folder_id TEXT, counts TEXT NOT NULL DEFAULT '{}');
CREATE INDEX source_movies ON source_files(movie_id);
CREATE INDEX jobs_pending ON jobs(state,lease_until);
CREATE INDEX sessions_active ON playback_sessions(revoked_at,lease_until);
